def count_nums(arr):
    def digit_sum(n):
        if n == 0:
            return 0
        s = 0
        sign = -1 if n < 0 else 1
        n = abs(n)
        while n > 0:
            s += n % 10 * sign
            n //= 10
            sign = 1
        return s
    return sum(1 for x in arr if digit_sum(x) > 0)
```

